/* { dg-output "OK" } */

package aaa;

// A catch-all handler that normal code also jumps to, with null on the
// stack: how Kawa compiles try-finally (guard, dynamic-wind) without jsr.
// javac never does this, so the class is assembled by hand (generated by a
// small script; version 49, so it needs no StackMapTable):
//
//   static int f(int x) {
//      0: iload_0  1: ifeq 6
//      4: aconst_null  5: athrow       ; when x != 0; caught by [0,6) -> 10 Throwable
//      6: aconst_null  7: goto 12      ; normal completion: null into the finally code
//     10: pop  11: aconst_null         ; catch handler, then the finally code
//     12: astore_1                     ; finally code, also the catch-all [0,12) -> 12
//     13: aload_1  14: ifnull 19  17: aload_1  18: athrow
//     19: bipush 7  21: ireturn
//   }
//
// OpenLDK took the value at 12 from the last caught exception even when
// normal code jumped there, so f(1) re-threw the NullPointerException the
// catch handler had already handled.
public class finallyentry extends ClassLoader
{
    private static final byte[] FINALLY = new byte[] {
        -54,-2,-70,-66,0,0,0,49,0,10,1,0,24,97,97,97,47,102,105,110,97,108,108,121,101,110,116,114,121,36,70,105,110,97,108,108,121,7,0,1,1,0,16,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,7,0,3,1,0,19,106,97,118,97,47,108,97,110,103,47,84,104,114,111,119,97,98,108,101,7,0,5,1,0,4,67,111,100,101,1,0,1,102,1,0,4,40,73,41,73,0,33,0,2,0,4,0,0,0,0,0,1,0,9,0,8,0,9,0,1,0,7,0,0,0,50,0,1,0,2,0,0,0,22,26,-103,0,5,1,-65,1,-89,0,5,87,1,76,43,-58,0,5,43,-65,16,7,-84,0,2,0,0,0,6,0,10,0,6,0,0,0,12,0,12,0,0,0,0,0,0
    };

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.finallyentry$Finally")) throw new ClassNotFoundException(name);
        return defineClass(name, FINALLY, 0, FINALLY.length);
    }

    static Object call(Class<?> c, int x)
    {
        try { return c.getMethod("f", int.class).invoke(null, x); }
        catch (java.lang.reflect.InvocationTargetException e) { return "escaped: " + e.getCause(); }
        catch (Throwable t) { return "escaped: " + t; }
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> c = new finallyentry().loadClass("aaa.finallyentry$Finally");
        String result = call(c, 0) + " " + call(c, 1);
        System.out.println("7 7".equals(result) ? "OK" : "FAIL: " + result);
    }
}
